// Unique moves, passives and ultimates of the San Francisco evolution lines
// (docs/ROSTER.md). Every name winks at the line's artist. NOT shared with other
// lines (only vinyl discs teach shared skills). Format: src/data/skills.js.
const L = (line, list) => list.map((s) => Object.assign({ line }, s));

